const input = $input.first().json;
const hour = new Date(input.hour_start_utc);
if (Number.isNaN(hour.valueOf()) || hour.getUTCMinutes() !== 0) throw new Error('Expected an exact UTC hour');
return [0, 15, 30, 45].map((minute) => { const instant = new Date(hour.getTime() + minute * 60000); const stamp = instant.toISOString().slice(0, 19).replace(/[-:T]/g, ''); return { json: { ...input, source_revision: `${stamp}.gkg.csv.zip`, observation_id: `gdelt-gkg-${stamp}`, observed_at_utc: instant.toISOString(), available_at_utc: new Date(instant.getTime() + 15 * 60000).toISOString(), source_url: `https://data.gdeltproject.org/gdeltv2/${stamp}.gkg.csv.zip` } }; });

const terms = ['euro', 'eur', 'dollar', 'usd', 'currency', 'forex', 'ecb', 'federal reserve'];
const inputs = $input.all();
if (inputs.length !== 4) throw new Error(`Expected four GDELT archives, got ${inputs.length}`);
const sources = []; let totalCount = 0; let weightedTone = 0;
for (let index = 0; index < inputs.length; index++) { const row = inputs[index].json; const binary = await this.helpers.getBinaryDataBuffer(index, 'data'); const digest = await crypto.subtle.digest('SHA-256', binary); const payload_sha256 = `sha256:${[...new Uint8Array(digest)].map((v) => v.toString(16).padStart(2, '0')).join('')}`; let count = 0; let toneSum = 0; for (const line of binary.toString('utf8').split(/\r?\n/)) { const fields = line.split('\t'); if (fields.length < 16) continue; const searchable = fields.slice(5, 15).join(' ').toLowerCase(); if (!terms.some((term) => searchable.includes(term))) continue; const tone = Number(fields[15].split(',', 1)[0]); if (Number.isFinite(tone)) { count++; toneSum += tone; } } totalCount += count; weightedTone += toneSum; sources.push({ observation_id: row.observation_id, source_revision: row.source_revision, observed_at_utc: row.observed_at_utc, available_at_utc: row.available_at_utc, payload_sha256, payload_path: `n8n://gdelt/${row.source_revision}` }); } const hour_start_utc = inputs[0].json.hour_start_utc; const canonical = JSON.stringify(sources); const aggregateDigest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical)); const aggregate_sha256 = `sha256:${[...new Uint8Array(aggregateDigest)].map((v) => v.toString(16).padStart(2, '0')).join('')}`; return [{ json: { source_id: 'gdelt-sentiment-prototype', hour_start_utc, hour_observation_id: `gdelt-h1-${hour_start_utc.replace(/[-:T.]/g, '').slice(0, 10)}`, source_records: sources, aggregate_sha256, article_count: totalCount, mean_tone: totalCount ? weightedTone / totalCount : 0, query_definition_version: inputs[0].json.query_definition_version, uncertainty_label: inputs[0].json.uncertainty_label, retrieved_at_utc: new Date().toISOString() } }];
